"""The in-memory link store."""
import random
import string

from shortener.urls import check_url

ALPHABET = string.digits + string.ascii_lowercase


class Store:
    """Maps short codes to URLs."""

    def __init__(self):
        self._urls = {}

    def add(self, url):
        """Store a URL and return its short code."""
        check_url(url)
        code = "".join(random.choice(ALPHABET) for _ in range(6))
        self._urls[code] = url
        return code

    def get(self, code):
        """Return the URL for a code, or None."""
        return self._urls.get(code)

